1	/**
2	 * GV-1 enforcement: the managed policy of this process.
3	 *
4	 * The two managed tiers (system and user) are read once per process, on first use, and kept frozen: a later change to
5	 * either file, to HOME or to anything else does not reach a running process. A managed file that exists and cannot be
6	 * used makes every use throw the same `ManagedPolicyError`; the files are not read again. A workspace's project file
7	 * is read per workspace (a process works in several: worktrees, a verify base tree) and merged under the tiers that
8	 * were already read, so a project file can only ever add restrictions to them.
9	 *
10	 * Who acts on it: index.ts reads it at startup (a broken managed file ends the process there); config.ts refuses at
11	 * launch what it disables; approval_policy.ts clamps every approval decision; dispatch_tool_call.ts applies its
12	 * command prefixes and egress allowlist; security.ts takes the protected paths, verification mode and inspector floor
13	 * from it; workspace_trust.ts asks it whether the trust variable counts; agent.ts clamps a runtime mode change.
14	 *
15	 * Nothing here reads an environment variable or a command-line argument, and nothing exported from here replaces,
16	 * relocates or switches off the process policy: `createPolicyHost` builds a separate host from explicit inputs (tests
17	 * use it), and the process host below is a module-private constant built from `resolveProductionPolicyInputs`.
18	 */
19	import * as path from "node:path";
20	import { resolveProductionPolicyInputs, type ProductionPolicyInputs } from "./managed_policy_inputs.js";
21	import {
22	  loadManagedTiers,
23	  loadProjectPolicy,
24	  ManagedPolicyError,
25	  MANAGED_POLICY_EXIT_CODE,
26	  recordProjectPolicyApproval,
27	  type LoadedPolicy,
28	  type ManagedTiers,
29	} from "./managed_policy_load.js";
