32	/** The managed tiers as read, and their merge (no project tier). Frozen. */
33	export interface ManagedPolicyState {
34	  tiers: ManagedTiers;
35	  effective: EffectivePolicy;
36	}
37	
38	/** What the caller knows about trust in a workspace; this module reads neither the trust store nor the environment. */
39	export interface WorkspaceTrustFacts {
40	  /** The operator's trust store lists the workspace. */
41	  workspaceTrusted: boolean;
42	  /** `NEXUS_TRUST_WORKSPACE=1` was set. */
43	  envTrustRequested: boolean;
44	}
45	
46	export interface PolicyHost {
47	  /** The managed tiers, read on the first call and never again. Throws the first call's `ManagedPolicyError` every time. */
48	  managed(): ManagedPolicyState;
49	  /** The policy in force in `workspace` (its real path): its project file merged under the managed tiers. */
50	  forWorkspace(workspace: string, trust: WorkspaceTrustFacts): LoadedPolicy;
51	  /**
52	   * Records the operator's approval of the workspace's current project file (by the hash of its bytes), so that its
53	   * relaxations apply until the file changes. Returns the hash, or undefined when there is no readable file to approve.
54	   */
55	  approveProjectPolicy(workspace: string, approvedAt: string): string | undefined;
56	}
