58	function deepFreeze<T>(value: T): T {
59	  if (value && typeof value === "object" && !Object.isFrozen(value)) {
60	    Object.freeze(value);
61	    for (const member of Object.values(value)) deepFreeze(member);
62	  }
63	  return value;
64	}
65	
66	/** A host over explicit inputs. `resolve` is called once for the managed tiers; only the approval store's path is taken from a later call. */
67	export function createPolicyHost(resolve: () => ProductionPolicyInputs): PolicyHost {
68	  let loaded: { inputs: ProductionPolicyInputs; state?: ManagedPolicyState; error?: ManagedPolicyError } | undefined;
69	  const managed = (): ManagedPolicyState => {
70	    if (!loaded) {
71	      const inputs = resolve();
72	      try {
73	        const tiers = loadManagedTiers(inputs);
74	        loaded = { inputs, state: deepFreeze({ tiers, effective: mergePolicies(tiers.system, tiers.user) }) };
75	      } catch (error) {
76	        if (!(error instanceof ManagedPolicyError)) throw error;
77	        loaded = { inputs, error };
78	      }
79	    }
80	    if (loaded.error) throw loaded.error;
81	    return loaded.state!;
82	  };
83	  const forWorkspace = (workspace: string, trust: WorkspaceTrustFacts): LoadedPolicy => {
84	    const { tiers } = managed();
85	    return loadProjectPolicy(tiers, { workspace, trust: { ...trust, storePath: resolve().trustStorePath }, fs: loaded!.inputs.fs });
86	  };
87	  return {
88	    managed,
89	    forWorkspace,
90	    approveProjectPolicy(workspace, approvedAt) {
91	      const sha256 = forWorkspace(workspace, { workspaceTrusted: true, envTrustRequested: false }).project.sha256;
92	      if (sha256 === undefined) return undefined;
93	      recordProjectPolicyApproval({ fs: loaded!.inputs.fs, storePath: resolve().trustStorePath, workspace, sha256, approvedAt });
94	      return sha256;
95	    },
96	  };
97	}
