155	/** `approval.require_human` against a call's effect class. */
156	export function humanRequirementForEffect(policy: EffectivePolicy, effect: string): HumanRequirement | undefined {
157	  if (!HUMAN_EFFECTS.includes(effect)) return undefined;
158	  const answer = requiresHuman(policy, effect as HumanEffect);
159	  return answer.required ? { message: answer.message!, source: answer.source } : undefined;
160	}
