162	/**
163	 * The approval settings as the policy lets them stand, whatever built them: mode `auto` becomes `review` under
164	 * `approval.disable_auto`, full access is dropped under `approval.disable_full_access`, and `human` (a managed
165	 * `prompt` rule or `approval.require_human`) makes the call ask in every mode. Restrict-only: nothing is ever raised.
166	 */
167	export function clampApprovalSettings<T extends ApprovalSettings>(policy: EffectivePolicy, settings: T, human?: HumanRequirement): T {
168	  const mode = settings.mode === "auto" && policy.approval.disable_auto.value ? "review" : settings.mode;
169	  const fullAccess = Boolean(settings.fullAccess) && !policy.approval.disable_full_access.value && mode === settings.mode;
170	  return { ...settings, mode, fullAccess, ...(human ? { policyRequiresHuman: true } : {}) };
171	}
172	
173	/** The tier to name beside a decision the approval mode made: the tier that disabled what was asked for, else the default. */
174	export function approvalDecisionSource(policy: EffectivePolicy, asked: ApprovalSettings): PolicySource {
175	  if (asked.mode === "auto" && policy.approval.disable_auto.value) return policy.approval.disable_auto.source;
176	  if (asked.fullAccess && policy.approval.disable_full_access.value) return policy.approval.disable_full_access.source;
177	  return { tier: "default", key: "approval.mode" };
178	}
