870	 * caller splits the command line; this module does not parse shell). A rule matches a segment that starts with its
871	 * words; any matching segment counts, and `forbid` outranks `prompt`. There is no allow outcome.
872	 */
873	export function decideManagedCommand(policy: EffectivePolicy, segments: readonly (readonly string[])[]): ManagedCommandDecision {
874	  const matching = (list: EffectiveList): SourcedItem | undefined =>
875	    list.items.find((item) => {
876	      const words = item.value.split(" ");
877	      return segments.some((segment) => segment.length >= words.length && words.every((word, i) => segment[i] === word));
878	    });
