677	program
678	  .command("verify")
679	  .description("Verify a change without a model: run the verifier on the base and on the change, and report VERIFIED, REGRESSION_FREE, UNVERIFIED or BLOCKED")
680	  .option("-w, --worktree <path>", "Top of the Git working tree (default: current directory); with no --head, its working tree is the change")
681	  .option("--base <ref>", "Commit the change starts from (default: HEAD)")
682	  .option("--head <ref>", "Commit that holds the change (default: the working tree)")
683	  .option("--verifier <command>", "Your own verifier command (otherwise one is discovered in the base tree and needs approval)")
684	  .option("--deliverable-file <path>", "Product file the change is meant to deliver, relative to the tree; VERIFIED needs at least one (repeatable)", collectDeliverableFile, [])
685	  .option("-y, --yes", "Approve whatever verifier is discovered in the base tree")
686	  .option("--approve-verifier <sha256>", "Approve the discovered verifier with exactly this digest (printed when approval is needed)")
687	  .option("--approve-verification-edit <path>", "Approve the change's edit to this verification file (a weakened test, CI, build or test configuration); it lifts BLOCKED and never makes the change VERIFIED (repeatable)", collectDeliverableFile, [])
688	  .option("--timeout-secs <n>", "Deadline of each verifier run, and of each side's type-checks, in seconds (default: NEXUS_VERIFIER_TIMEOUT_SECS, else 300)")
689	  .option("--sandbox [engine]", "Confine every process verify starts on repository code: auto, bwrap or docker (default: auto); none explicitly opts out")
690	  .option("--sandbox-network", "Let sandboxed verification processes use the network (off by default; incompatible with --sandbox none)")
691	  .option("--receipt <file>", "Also write the result document (the receipt) to this file")
692	  .option("-j, --json", "Print the result as one JSON document on stdout (see the manual: nexus verify)")
693	  .action(async (_options: any, cmd: Command) => {
694	    const options = commandOptions(cmd);
695	    const isJson = Boolean(options.json);
696	    const fail = (name: "usage" | "interrupted", message: string) => {
697	      const exitCode = verifyExitCode(name);
698	      console.error(`error: ${formatDiagnosticForOutput(message)}`);
699	      if (isJson) console.log(JSON.stringify({ schema_version: VERIFY_RESULT_SCHEMA_VERSION, error: redactDiagnosticForOutput(message), exitCode } satisfies VerifyJsonError, null, 2));
700	      exitAfterFlush(exitCode);
701	    };
702	    let timeoutSecs: number | undefined;
703	    if (options.timeoutSecs !== undefined) {
704	      timeoutSecs = Number(options.timeoutSecs);
705	      if (!Number.isInteger(timeoutSecs) || timeoutSecs < 1 || timeoutSecs > 86_400) return fail("usage", "--timeout-secs must be a whole number of seconds from 1 to 86400");
706	    }
707	    if (options.verifier !== undefined && !String(options.verifier).trim()) return fail("usage", "--verifier needs a command");
708	    if (options.approveVerifier !== undefined && !/^[0-9a-fA-F]{64}$/.test(String(options.approveVerifier).trim())) return fail("usage", "--approve-verifier needs the 64-character sha256 digest printed when approval is needed");
709	    if (options.verifier !== undefined && (options.yes || options.approveVerifier !== undefined)) return fail("usage", "--verifier is your own command and needs no approval: do not combine it with --yes or --approve-verifier");
710	    // Verification executes repository code, so confinement is the default. `none` is an explicit opt-out.
711	    let sandbox: VerifySandboxRequest | undefined;
712	    if (options.sandbox === "none") {
713	      sandbox = { engine: "none" };
714	    } else if (options.sandbox === undefined || options.sandbox === false) {
715	      if (options.sandboxNetwork) sandbox = { engine: "auto", network: true };
716	    } else if (options.sandbox === true) {
717	      sandbox = { engine: "auto", network: Boolean(options.sandboxNetwork) };
718	    } else {
719	      const engine = options.sandbox === true ? "auto" : String(options.sandbox);
720	      if (engine !== "auto" && engine !== "bwrap" && engine !== "docker") return fail("usage", "--sandbox takes auto, bwrap, docker or none");
721	      sandbox = { engine, network: Boolean(options.sandboxNetwork) };
722	    }
723	    if (options.sandboxNetwork && sandbox?.engine === "none") return fail("usage", "--sandbox-network cannot be used with --sandbox none");
724	
725	    // The first signal stops verification once the running verifier process ends; a second one exits at once.
726	    const abort = new AbortController();
727	    const onSignal = () => {
728	      if (abort.signal.aborted) process.exit(verifyExitCode("interrupted"));
729	      abort.abort();
730	      if (!isJson) console.error(pc.yellow("\nInterrupt received: stopping after the running verifier process (signal again to exit at once)."));
731	    };
732	    process.on("SIGINT", onSignal);
733	    process.on("SIGTERM", onSignal);
734	    try {
735	      const result = await verifyChange(
736	        { worktree: path.resolve(options.worktree ?? process.cwd()), base: options.base, head: options.head },
737	        {
738	          verifierCommand: options.verifier,
739	          approveDiscoveredVerifier: Boolean(options.yes),
740	          approvedVerifierDigest: options.approveVerifier,
741	          deliverables: options.deliverableFile ?? [],
742	          approvedVerificationEdits: options.approveVerificationEdit ?? [],
743	          timeoutSecs,
744	          sandbox,
745	          signal: abort.signal,
746	          onProgress: isJson ? undefined : (message) => console.error(pc.dim(message)),
747	        },
748	      );
749	      const document = `${JSON.stringify(result, null, 2)}\n`;
750	      if (options.receipt !== undefined) {
751	        try {
752	          fs.writeFileSync(path.resolve(String(options.receipt)), document);
753	        } catch (err: any) {
754	          return fail("usage", `--receipt: cannot write ${options.receipt} (${err?.code ?? "error"}); the verdict was ${result.verdict}`);
755	        }
756	      }
757	      if (isJson) process.stdout.write(document);
758	      else console.log(renderVerifyText(result));
759	      exitAfterFlush(result.exitCode);
760	    } catch (err: any) {
761	      if (err instanceof VerifyUsageError) return fail("usage", err.message);
762	      if (err instanceof VerifyInterrupted) return fail("interrupted", "interrupted: no verdict was reached");
763	      throw err;
764	    } finally {
765	      process.removeListener("SIGINT", onSignal);
766	      process.removeListener("SIGTERM", onSignal);
767	    }
768	  });
